csharp\nusing Firebase.Extensions;\nusing Firebase.Functions;\nusing System.Threading.Tasks;\n\nnamespace AirHockey.Networking.Lobby\n{\n /// <summary>Appelle la Cloud Function createMatch pour récupérer un room ID.</summary>\n public static class MatchmakingService\n {\n private static readonly FirebaseFunctions functions = FirebaseFunctions.DefaultInstance;\n\n public static async Task<string> FindMatchAsync(int elo)\n {\n var data = new System.Collections.Generic.Dictionary<string, object>\n {\n { \"elo\", elo }\n };\n\n var func = functions.GetHttpsCallable(\"createMatch\");\n var resp = await func.CallAsync(data).ConfigureAwait(false);\n var room = resp.Data as string;\n return room;\n }\n }\n}\n